// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null, points: row.points ?? meta.points,
      ...(Number.isInteger(numericAnswer) ? {numericAnswer, questionNote: 'В тренировочном рейтинге за эту задачу баллы не начисляются.'} : {}),
      ...(audio ? {audio: folder + 'listening.mp3'} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  return {
    id: year + '-' + subject + '-' + grade, year, grades, label: grades.join('–') + ' классы',
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2025,"grade":"3-4","contest":"Золотое руно","letters":"ABCD","count":30,"language":"ru","points":3,"tasksFile":"tasks.pdf","answersFile":"answers.pdf"}, [{"title":"Транспорт бедуинов","question":"Основной транспорт бедуинов – ....","choices":["корабль","верблюд","самолёт","велосипед"],"answer":1,"steps":["Бедуины традиционно кочевали по засушливым местностям. Им нужно было перевозить людей и поклажу на большие расстояния.","Верблюд может долго обходиться без воды и нести груз по песку. Поэтому бедуины традиционно ездили на верблюдах."]},{"title":"Название стран Африки","question":"Страны Северной Африки во времена мусульманских завоевательных походов получили название от арабского слова «запад» – ....","choices":["Магриб","Марокко","Мавритания","Атлас"],"answer":0,"steps":["В вопросе нужно найти название целого региона. Марокко и Мавритания — отдельные страны, а Атлас — горная система.","Арабское «аль-Магриб» означает «запад». Так стали называть западную часть Северной Африки."]},{"title":"Пост в Рамадан","question":"В течение священного месяца Рамадан мусульмане соблюдают пост: не принимают пищу и не пьют воду ....","choices":["по пятницам","от рассвета до заката солнца","два дня подряд","от заката до восхода солнца"],"answer":1,"steps":["У поста в Рамадан есть ежедневные границы. Утренний приём пищи заканчивают до рассвета.","После заката пост этого дня завершается и можно есть и пить. Значит, пост длится от рассвета до заката солнца."]},{"title":"Почётная одежда","question":"В арабском языке это слово означало почётную одежду, которая могла быть подарена как знак отличия.","choices":["Мантия","Мундир","Сарафан","Халат"],"answer":3,"steps":["В этимологическом словаре можно узнать, что по-арабски «хильат» означало почётное одеяние. Такое одеяние жаловали в знак отличия.","Через тюркские языки это слово попало в русский язык в форме «халат». Сейчас у слова есть и привычное бытовое значение."]},{"title":"Названия животного","question":"В арабском языке существуют сотни слов для обозначения этого животного, его качеств и состояний.","choices":["Лошадь","Мышь","Лев","Верблюд"],"answer":3,"steps":["Для жителей Аравии это животное было особенно важно в дороге и хозяйстве. На нём ездили, перевозили грузы, а его молоко употребляли в пищу.","В арабском языке есть отдельные слова для верблюдов разного возраста, окраса и назначения. Вопрос посвящён верблюду."]},{"title":"Волшебное заклинание","question":"Одно из названий кунжута было частью волшебного заклинания в сказке ....","choices":["Маруф-башмачник","Халиф на час","Синдбад-мореход","Али-Баба и сорок разбойников"],"answer":3,"steps":["У кунжута есть другое название — сезам. В сказочном заклинании можно встретить и форму «Сим-сим».","Слова «Сезам, откройся!» открывают вход в пещеру с сокровищами. Этот эпизод есть в сказке «Али-Баба и сорок разбойников»."]},{"title":"Благодарная рыба","question":"Благодарная рыба из одноимённой сказки превратилась в ....","choices":["феллаха","кади","бедуина","факира (дервиша)"],"answer":3,"steps":["Отец Хасана ловил рыбу в море. Трижды Хасан отпускал маленькую рыбку, которую приносил отец. Позже он встретил в дороге бедного странника и поделился с ним хлебом.","В конце сказки дервиш признаётся Хасану, что он и был той рыбкой. Значит, ответ — «факира (дервиша)»."]},{"title":"По следам волшебных рыб","question":"В «Сказке о рыбаке» путешествие в поисках правды о волшебных рыбах привело царя к ....","choices":["джинну","дворцу","морю","рыбаку"],"answer":1,"steps":["Царь узнал, что разноцветных рыб поймали в пруду, и отправился туда. Ночью он один пошёл искать того, кто сможет объяснить происхождение рыб.","Поиски привели его к дворцу из чёрного камня. Там царь встретил юношу, наполовину превращённого в камень, и узнал историю рыб."]},{"title":"Мультфильм по сказке","question":"Этот диснеевский мультфильм был создан по мотивам одной из сказок «Тысячи и одной ночи».","choices":["«Русалочка»","«Аладдин»","«Моана»","«Холодное сердце»"],"answer":1,"steps":["В «Тысяче и одной ночи» есть история о юноше, который находит волшебную лампу с джинном.","Такой герой и лампа есть в диснеевском мультфильме «Аладдин»."]},{"title":"Надпись на часовой башне","question":"Эти слова написаны над северным и южным циферблатами самой высокой в мире часовой башни.","choices":["Время разрушит все стены","Боже, храни короля","Аллах велик","В единстве – сила"],"answer":2,"steps":["На фотографии показана часовая башня в Мекке. Над её четырьмя циферблатами расположены арабские надписи.","Над северным и южным циферблатами написано «Аллаху акбар». Этой фразе в списке соответствует перевод «Аллах велик»."],"figure":{"src":"assets/golden-fleece/2025/3-4-10.webp","alt":"Высокая башня с часами и полумесяцем над площадью.","width":287,"height":336}},{"title":"Башня в Севилье","question":"Башня, служившая раньше минаретом Большой мечети Севильи, называется ....","choices":["Альгамбра","Аль-Кутубия","Хиральда","Алькасар"],"answer":2,"steps":["Минарет — башня при мечети. В Севилье прежний минарет Большой мечети сохранили и превратили в колокольню собора.","Эту колокольню называют Хиральдой. Алькасар тоже находится в Севилье, но это дворцовый комплекс."],"figure":{"src":"assets/golden-fleece/2025/3-4-11.webp","alt":"Башня с узорчатым фасадом и ярусной верхушкой.","width":282,"height":323}},{"title":"Устье Шатт-эль-Араба","question":"В этот залив впадает река Шатт-эль-Араб, образующаяся при слиянии Тигра и Евфрата.","choices":["Персидский","Оманский","Арабский","Аденский"],"answer":0,"steps":["На карте найди, где Тигр и Евфрат сходятся на юге Ирака. Ниже слияния общая река называется Шатт-эль-Араб.","Проследи её течение к юго-востоку, вдоль границы Ирака и Ирана. В устье река впадает в Персидский залив."]},{"title":"Торговый путь на восток","question":"Торговый маршрут, связывавший скандинавские страны с арабскими, назывался ....","choices":["Транссахарский торговый путь","Великий Волжский путь","Бахрейнский жемчужный путь","Великий чайный путь"],"answer":1,"steps":["Купцы из Скандинавии через Балтийское море и реки Восточной Европы выходили на Волгу. Из Волги можно было попасть в Каспийское море и дальше к рынкам халифата.","Вдоль этого маршрута археологи находят арабские серебряные монеты. По главной реке маршрут называют Великим Волжским путём."]},{"title":"Город в эпоху Аббасидов","question":"Этот город стал центром средневековой арабской культуры в эпоху правления династии Аббасидов.","choices":["Басра","Дамаск","Багдад","Медина"],"answer":2,"steps":["В 762 году халиф аль-Мансур из династии Аббасидов основал новую столицу на реке Тигр.","Эта столица — Багдад. В город приезжали учёные, а переводчики знакомили читателей с научными трудами на арабском языке."]},{"title":"Столица набатеев","question":"Этот город был столицей Набатейского царства.","choices":["Багдад","Дамаск","Иерусалим","Петра"],"answer":3,"steps":["На фотографии видны фасады, высеченные прямо в скалах. Такие здания и гробницы сохранились в древней столице набатеев на территории современной Иордании.","Этот город стоял на перекрёстке караванных путей и назывался Петра."],"figure":{"src":"assets/golden-fleece/2025/3-4-15.webp","alt":"Фасады и проёмы, высеченные в скалах.","width":315,"height":272}},{"title":"Резиденция правителей","question":"Этот памятник архитектуры был резиденцией правителей последнего арабского государства в Европе.","choices":["Альгамбра","Мескита","Медина Асаара","Хиральда"],"answer":0,"steps":["Речь идёт о Гранадском эмирате на юге Пиренейского полуострова. Им управляла династия Насридов.","В Гранаде сохранился дворцовый и крепостной комплекс Насридов — Альгамбра. Именно здесь была их резиденция."],"figure":{"src":"assets/golden-fleece/2025/3-4-16.webp","alt":"Дворцовый комплекс с башнями над зелёными деревьями.","width":400,"height":226}},{"title":"Имя полководца в названии","question":"Этот европейский город получил свое название от имени арабского полководца Тарика ибн Зияда.","choices":["Сеута","Гибралтар","Кадис","Картахена"],"answer":1,"steps":["Войско Тарика ибн Зияда высадилось у скалы на юге Пиренейского полуострова. Её стали называть «Джабаль Тарик», то есть «гора Тарика».","Со временем из этого арабского названия получилось слово «Гибралтар». То же название носит город у скалы."]},{"title":"Предание о сотворении","question":"По исламским представлениям, сначала Аллах создал ....","choices":["Адама и Хавву","Трон и воду","ангелов и джиннов","небо и землю"],"answer":1,"steps":["В одном из хадисов о начале творения говорится, что Трон Аллаха находился над водой ещё до сотворения небес и земли.","Оба предмета, упомянутые в этом раннем эпизоде, собраны в одном варианте — «Трон и воду»."]},{"title":"Отпечаток на камне","question":"Отпечаток ноги этого пророка, согласно преданию, остался на камне во время строительства Каабы.","choices":["Ибрахим","Исхак","Аль-Яса","Закарийя"],"answer":0,"steps":["Камень рядом с Каабой называют «Макам Ибрахим», то есть «место стояния Ибрахима».","Согласно преданию, пророк Ибрахим стоял на этом камне, когда возводил стены Каабы. С ним и связывают отпечаток."]},{"title":"Меч из преданий","question":"Согласно легендам, этот меч в руках пророка Мухаммеда приобрёл волшебные свойства.","choices":["Самсамха","Зульфикар","Халеф","Шамшир-е Зоморроднегар"],"answer":1,"steps":["В преданиях есть меч, который принадлежал Мухаммеду и затем перешёл к его родственнику Али.","Этот легендарный меч называется Зульфикар. На изображениях его часто можно узнать по раздвоенному острию."]},{"title":"Рождение Исы","question":"В этом городе родился исламский пророк Иса ибн Марьям.","choices":["Вифлеем","Назарет","Дамаск","Мекка"],"answer":0,"steps":["Иса ибн Марьям означает «Иса, сын Марьям». Так в исламе называют Иисуса, сына Марии.","Местом его рождения считают Вифлеем, город к югу от Иерусалима. Назарет связан с его детством."]},{"title":"Гробница в мечети","question":"В этой мечети находится могила пророка Мухаммеда.","choices":["Аль-Акса в Иерусалиме","Аль-Харам в Мекке","Аль-Масджид ан-Набави в Медине","Айя-София в Стамбуле"],"answer":2,"steps":["Мухаммед умер в Медине и был похоронен в комнате своей жены Аиши. Позднее это помещение вошло в состав мечети.","Это мечеть Аль-Масджид ан-Набави, название которой переводится как «Мечеть Пророка». Над местом погребения расположен зелёный купол."],"figure":{"src":"assets/golden-fleece/2025/3-4-22.webp","alt":"Большой двор мечети с несколькими высокими минаретами.","width":240,"height":253}},{"title":"Ковёр для мечети","question":"Для этой мечети был изготовлен самый большой в мире ковёр, выполненный вручную.","choices":["Мечеть аль-Харам","Мечеть шейха Заида","Мечеть аль-Акса","Мечеть султана Хасана"],"answer":1,"steps":["По Книге рекордов Гиннесса, площадь ковра — 5 630 квадратных метров. Его сделали вручную для главного молитвенного зала мечети в Абу-Даби.","Белые купола и цветочный узор во дворе на фотографии принадлежат той же мечети. Это мечеть шейха Заида."],"figure":{"src":"assets/golden-fleece/2025/3-4-23.webp","alt":"Белая мечеть за двором с цветочным узором.","width":237,"height":291}},{"title":"Арка в архитектуре","question":"Этот тип арки – характерный элемент исламской архитектуры.","choices":["Прямоугольная","Подковообразная","Треугольная","Ползучая"],"answer":1,"steps":["Проследи внутреннюю границу арок на фотографии. Ниже самого широкого места дуга с обеих сторон загибается внутрь.","Такой изгиб напоминает подкову, концы которой сближаются. Такая арка называется подковообразной."],"figure":{"src":"assets/golden-fleece/2025/3-4-24.webp","alt":"Ряд округлых арок на колоннах вдоль двора.","width":305,"height":237}},{"title":"Мечеть на месте храма","question":"Эта мечеть в Сирии перестроена из христианской базилики, возведённой на месте античного храма.","choices":["Мечеть Омейядов","Великая мечеть Алеппо","Мечеть Наби Хабиль","Мечеть Халида ибн аль-Валида"],"answer":0,"steps":["В старом Дамаске на месте римского храма Юпитера была христианская церковь, связанная с почитанием Иоанна Крестителя.","В начале VIII века халиф аль-Валид I из династии Омейядов распорядился устроить здесь большую мечеть. Она известна как мечеть Омейядов."],"figure":{"src":"assets/golden-fleece/2025/3-4-25.webp","alt":"Минарет над аркадой вдоль двора мечети.","width":237,"height":303}},{"title":"Мечеть в Иране","question":"Эту мечеть, расположенную в Иране, отличает отсутствие минаретов.","choices":["Мечеть шейха Заида","Мечеть шейха Лотфаллы","Мечеть аль-Харам","Мечеть Султанахмет"],"answer":1,"steps":["На снимке виден купол, а привычных башен-минаретов рядом нет. Так выглядит одна из мечетей на площади Накш-е Джахан в иранском Исфахане.","Она была построена при шахе Аббасе I. Это мечеть шейха Лотфаллы, которую легко отличить по отсутствию минаретов."],"figure":{"src":"assets/golden-fleece/2025/3-4-26.webp","alt":"Мечеть с куполом и отражением в бассейне.","width":338,"height":212}},{"title":"Высотные дома в пустыне","question":"В этом городе сохранились многоэтажные постройки XVI века, за что его иногда называют «Манхэттен в пустыне».","choices":["Джидда","Шибам","Дубай","Петра"],"answer":1,"steps":["В вопросе важен XVI век. На фотографии видны тесно стоящие старинные дома в несколько этажей, сложенные из необожжённого кирпича.","Такой город сохранился в Йемене. Это Шибам, который из-за домов-башен называют «Манхэттеном в пустыне»."],"figure":{"src":"assets/golden-fleece/2025/3-4-27.webp","alt":"Плотный ряд высоких домов с плоскими крышами.","width":334,"height":221}},{"title":"Музей в Абу-Даби","question":"Название этого художественного музея в Абу-Даби совпадает с названием всемирно известного парижского музея.","choices":["Эрмитаж","Лувр","Орсэ","Прадо"],"answer":1,"steps":["Лувр и Орсэ находятся в Париже, Эрмитаж — в Санкт-Петербурге, а Прадо — в Мадриде. Для ответа осталось проверить два парижских названия.","По соглашению Франции и Объединённых Арабских Эмиратов от 2007 года музей в Абу-Даби получил имя «Лувр». На фотографии виден его огромный ажурный купол."],"figure":{"src":"assets/golden-fleece/2025/3-4-28.webp","alt":"Музей с широким куполом над белыми зданиями у воды.","width":340,"height":204}},{"title":"Книга о механизмах","question":"Этот учёный описал в своём трактате «Книга знаний об остроумных механических устройствах» множество собственных изобретений и усовершенствований механизмов: водяные часы, коленчатый вал и даже роботов.","choices":["Аль-Бируни","Аль-Хорезми","Аль-Фергани","Аль-Джазари"],"answer":3,"steps":["В трактате есть необычные устройства, которые можно узнать по рисункам. Например, в водяных часах с фигурой слона поплавок приводит фигурки в движение.","Тот же инженер описал насос, в котором вращение колеса заставляет поршни двигаться вперёд и назад. Это изобретения Аль-Джазари."]},{"title":"Имя священного города","question":"Название этого священного для мусульман города стало нарицательным для обозначения популярного туристического места.","choices":["Кум","Мекка","Петра","Хеврон"],"answer":1,"steps":["Мусульмане совершают хадж — паломничество к Каабе в священном городе Саудовской Аравии. Этот город — Мекка.","Из-за того что туда стремятся паломники со всего мира, слово «мекка» стали употреблять и в переносном смысле. Например, туристической меккой называют место, куда стремится множество путешественников."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
